WITH base AS (SELECT *, INITCAP(TRIM(device)) AS device_title FROM sessions WHERE started_at >= TIMESTAMP '2023-11-10 00:00:00' AND customer_id IS NOT NULL AND country = 'UK') SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS seq_no, FIRST_VALUE(country) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY country, browser ORDER BY started_at, id) AS event_seq FROM base
